begin;
create table trade_business.purchase_orders(company_id uuid not null,id uuid not null,order_id uuid not null,order_version integer not null,no text not null,supplier_id uuid not null,supplier_kind text not null default 'supplier' check(supplier_kind='supplier'),state text not null default 'draft' check(state in ('draft','submitted','confirmed','cancelled')),version integer not null default 1 check(version>0),currency text not null check(currency in ('USD','CNY','EUR','GBP','HKD','JPY')),day date not null,due_day date not null,payload jsonb not null,total_minor numeric(38,0) not null check(total_minor>=0),created_by uuid not null,primary key(company_id,id),unique(company_id,no),unique(company_id,order_id,id),foreign key(company_id,order_id,order_version) references trade_business.order_versions(company_id,order_id,version),foreign key(company_id,supplier_kind,supplier_id) references trade_business.business_records(company_id,kind,id),check(due_day>=day));
create index purchases_order on trade_business.purchase_orders(company_id,order_id,state);
create table trade_business.purchase_lines(company_id uuid not null,id uuid not null,purchase_id uuid not null,order_id uuid not null,order_line_id uuid not null,quantity numeric(24,4) not null check(quantity>0),unit_cost numeric(24,4) not null check(unit_cost>=0),amount_minor numeric(38,0) not null check(amount_minor>=0),snapshot jsonb not null,primary key(company_id,id),unique(company_id,purchase_id,id),unique(company_id,order_id,id),foreign key(company_id,order_id,purchase_id) references trade_business.purchase_orders(company_id,order_id,id),foreign key(company_id,order_id,order_line_id) references trade_business.order_lines(company_id,order_id,id));
create index purchase_lines_source on trade_business.purchase_lines(company_id,order_line_id);
create table trade_business.receipts(company_id uuid not null,id uuid not null,purchase_id uuid not null,day date not null,created_by uuid not null,primary key(company_id,id),unique(company_id,purchase_id,id),foreign key(company_id,purchase_id) references trade_business.purchase_orders(company_id,id));
create table trade_business.receipt_lines(company_id uuid not null,id uuid not null,receipt_id uuid not null,purchase_id uuid not null,purchase_line_id uuid not null,order_id uuid not null,order_line_id uuid not null,quantity numeric(24,4) not null check(quantity>0),primary key(company_id,id),unique(company_id,order_id,order_line_id,id),foreign key(company_id,purchase_id,receipt_id) references trade_business.receipts(company_id,purchase_id,id),foreign key(company_id,purchase_id,purchase_line_id) references trade_business.purchase_lines(company_id,purchase_id,id),foreign key(company_id,order_id,order_line_id) references trade_business.order_lines(company_id,order_id,id));
create index receipt_lines_source on trade_business.receipt_lines(company_id,purchase_line_id);
grant select,insert on trade_business.purchase_orders,trade_business.purchase_lines,trade_business.receipts,trade_business.receipt_lines to business_backend;
grant update(state,version) on trade_business.purchase_orders to business_backend;
commit;
